findings = '## Case 81 — Chain Replication findings\n\n973. **replica multiplicity ≠ replica-role equivalence** — head, middle, and tail can all retain object state while having different ingress, query, completion, and forwarding authority;\n974. **head receipt/application ≠ client-view completed history** — the paper defines the service history from the tail, while requests received upstream but not yet tail-processed remain pending;\n975. **tail processing ≠ client knowledge of success** — a reply can be lost after processing, so retries of non-idempotent updates require separate client precautions;\n976. **proof-model `Hist` ≠ required complete implementation history** — the paper explicitly says an implementation would probably store the current object value rather than the update sequence used for the proof;\n977. **`Sent_i` ≠ object/application history** — it is bounded in-process state for forwarded updates whose tail completion might not yet be known;\n978. **tail acknowledgement ≠ payload replication itself** — `ack(r)` is control evidence propagated backward after tail processing, while the update state has already propagated forward;\n979. **ack-driven `Sent` retirement ≠ payload erasure** — forgetting a completed forwarding obligation does not undo or sanitize the object update;\n980. **failure removal from the chain ≠ payload deletion** — membership/role reconfiguration changes which surviving replicas participate in service without establishing physical erase of a failed server\'s medium;\n981. **internal replica failure ≠ blind neighbor reconnection** — the new predecessor/successor edge first closes its possible update gap before later forwarding proceeds normally;\n982. **successor progress evidence ≠ full state transfer** — the successor\'s last-received sequence number lets the predecessor send only the missing suffix of retained in-process updates;\n983. **new-tail payload copy ≠ immediate tail authority** — state transfer may overlap ordinary traffic, and concurrent deltas plus the invariant must be closed before the new replica begins serving as tail;\n984. **role transfer ≠ payload relocation alone** — tail admission also changes master/client configuration about which replica may serve tail operations;\n985. **continued service on a shortened chain ≠ restored fault-tolerance margin** — server removal can preserve service while reducing the number of further failures tolerated, motivating later chain extension;\n986. **configuration state ≠ object payload** — predecessor/successor/head/tail relations determine how otherwise surviving replicas may act;\n987. **Chain Replication ≠ invention of primary/backup or state-machine replication** — the OSDI paper explicitly places itself inside those earlier protocol families;\n988. **fail-stop proof scope ≠ partition/Byzantine/deployment guarantee** — the bounded result depends on the stated failure/configuration model and prototype/simulation evidence does not automatically extend beyond it.\n'

def insert_after_unique(path, anchor, new_line):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    if new_line in text:
        return
    lines = text.splitlines()
    hits = [i for i, line in enumerate(lines) if anchor in line]
    if len(hits) != 1:
        raise SystemExit(f"{path} anchor count for {anchor!r} = {len(hits)}")
    lines.insert(hits[0] + 1, new_line)
    p.write_text("\n".join(lines) + "\n", encoding="utf-8")

if Path(CASE_PATH).exists() or Path(EVIDENCE_PATH).exists():
    raise SystemExit("Case 81 path already exists; refusing duplicate integration")

Path(CASE_PATH).write_text(case_text, encoding="utf-8")
Path(EVIDENCE_PATH).write_text(evidence_text, encoding="utf-8")

insert_after_unique(
    "README.md",
    "Case 80 — Apache HDFS DataNode Decommissioning:",
    readme_line,
)
insert_after_unique(
    "ROADMAP.md",
    "HDFS DataNode decommission / planned replica drain",
    roadmap_line,
)
insert_after_unique(
    "CASE_INDEX.md",
    "[Apache HDFS DataNode Decommissioning: Administrative Retirement, Replication Drain, and Recommission](cases/80-apache-hdfs-datanode-decommission-replica-drain.md)",
    case_index_row,
)
insert_after_unique(
    "CASE_INDEX.md",
    "| HDFS DataNode decommission / 2008–2016 bounded regime |",
    matrix_row,
)

p = Path("CASE_INDEX.md")
text = p.read_text(encoding="utf-8")
old = "After eighty-one bounded cases, **all eighty-one cases are now `grounded`.**"
new = "After eighty-two bounded cases, **all eighty-two cases are now `grounded`.**"
if text.count(old) != 1:
    raise SystemExit(f"aggregate-status anchor count = {text.count(old)}")
text = text.replace(old, new, 1)
if "## Case 81 — Chain Replication findings" in text:
    raise SystemExit("Case 81 findings unexpectedly already present")
text = text.rstrip() + "\n\n" + findings.rstrip() + "\n"
p.write_text(text, encoding="utf-8")

for path in ["README.md", "ROADMAP.md", "CASE_INDEX.md"]:
    t = Path(path).read_text(encoding="utf-8")
    if CASE_PATH not in t:
        raise SystemExit(f"missing Case 81 navigation in {path}")
    if EVIDENCE_PATH not in t:
        raise SystemExit(f"missing Case 81 evidence navigation in {path}")

idx = Path("CASE_INDEX.md").read_text(encoding="utf-8")
if "After eighty-two bounded cases" not in idx:
    raise SystemExit("aggregate status not updated")
if not any(line.startswith("973.") for line in idx.splitlines()):
    raise SystemExit("finding 973 missing")
if not any(line.startswith("988.") for line in idx.splitlines()):
    raise SystemExit("finding 988 missing")

subprocess.run(["git", "diff", "--check"], check=True)
